import { Component } from '@angular/core';

@Component({
  selector: 'product-list',
  templateUrl: './product-list.component.html',
  styleUrls: ['./product-list.component.css']
})
export class ProductListComponent {
  name = "Mohan";
  product ={
    name : 'Iphone 13',
    price : 799,
    color : 'Black',
    Discount : 8.5,
    instock : 0,
    pImage : '/assets/images/iphone.png'
  }
  getDiscount(){
    return this.product.price-(this.product.price * this.product.Discount / 100)
  }
  OnNameChange(event : any){
    this.name= event.target.value;
  }
}
<div class="product-cont">
    <img [src]="product.pImage" width="400px">
    <p>Name :{{ product.name }}</p>
    <p>Price :{{ '$'+product.price }}</p>
    <p>Color :{{ product.color }}</p>
    <p>Discount :{{ '$' + getDiscount().toFixed(2) }}</p>
    <p>{{ product.instock > 0 ? 'Only ' + product.instock + ' Items Left' : 'Not in Stock' }}</p>
    <!-- <button [disabled]="!( product.instock > 0)">Buy Now</button>
    <input (input)="OnNameChange($event)">
    <p>Name : {{name}}</p> -->
    <button>-</button>
    <button>+</button>
</div>
